import json, random, sys
sys.path.insert(0, '/workspace/submission')
import main as M

ok = True
for extra in range(0, 8):
    arr_raw = ('{"zones":' + '[' * extra + ']' * extra + ',"profiles":[{"id":"p",'
               '"max_aliases":4,"cname":"follow","wildcard":"rfc"}],"queries":[],"observations":[]}')
    if extra == 0:
        arr_raw = arr_raw.replace('"zones":,', '"zones":[],')
    obj_raw = ('{"zones":' + '{"a":' * extra + '1' + '}' * extra +
               ',"profiles":[{"id":"p","max_aliases":4,"cname":"follow",'
               '"wildcard":"rfc"}],"queries":[],"observations":[]}')
    if extra == 0:
        obj_raw = obj_raw.replace('"zones":,', '"zones":{},')
    for label, raw in (('arr', arr_raw), ('obj', obj_raw)):
        try:
            json.loads(raw)
        except Exception as exc:
            print('test harness produced invalid json for %s extra=%d: %s' % (label, extra, exc))
            continue
        total = 1 + extra
        expect = total <= M.MAX_DEPTH
        got = M.nesting_within_limit(raw.encode())
        if got != expect:
            ok = False
            print('BAD %s extra=%d total=%d got=%s expect=%s' % (label, extra, total, got, expect))
print('valid-JSON depth boundaries exact:', ok)

rng = random.Random(31337)
def rnd_value(rng, depth):
    if depth == 0:
        return rng.choice([1, -2, 0, 'txt', 'a"b', 'back\\slash', '[bracket]', '{brace}', '',
                           '"quoted"', '}odd{', 'x' * 40, 3.5, None, True, 'deep'])
    kind = rng.randrange(4)
    if kind == 0:
        return [rnd_value(rng, depth - 1) for _ in range(rng.randint(0, 3))]
    if kind == 1:
        return {str(i): rnd_value(rng, depth - 1) for i in range(rng.randint(0, 3))}
    if kind == 2:
        return rng.choice([1, 'str', None])
    return [rng.choice(['"', '\\', '}', '{', ']', '[']) for _ in range(rng.randint(0, 5))]
bad = 0
for i in range(30000):
    doc = {'zones': [rnd_value(rng, 3)],
           'profiles': [{'id': 'p', 'max_aliases': 2, 'cname': 'follow', 'wildcard': 'rfc'}],
           'queries': [], 'observations': []}
    raw = json.dumps(doc)
    json.loads(raw)
    if not M.nesting_within_limit(raw.encode()):
        bad += 1
        if bad < 3:
            print('FALSE REJECTION at trial %d: %r' % (i, raw[:160]))
print('false rejections on random valid documents: %d / 30000' % bad)
PYEOF
